package com.smartlibrary.model;
public class Book {
 private final String id; private String title,author,isbn,category,description; private int totalCopies,availableCopies,readingMinutes,learningValue;
 public Book(String id,String title,String author,String isbn,String category,String description,int totalCopies,int availableCopies,int readingMinutes,int learningValue){if(id==null||id.isBlank()||title==null||title.isBlank())throw new IllegalArgumentException("Book ID and title required");if(totalCopies<0||availableCopies<0||availableCopies>totalCopies||readingMinutes<0)throw new IllegalArgumentException("Invalid counts");this.id=id;this.title=title;this.author=n(author);this.isbn=n(isbn);this.category=n(category);this.description=n(description);this.totalCopies=totalCopies;this.availableCopies=availableCopies;this.readingMinutes=readingMinutes;this.learningValue=learningValue;}
 private static String n(String s){return s==null?"":s;} public String getId(){return id;}public String getTitle(){return title;}public String getAuthor(){return author;}public String getIsbn(){return isbn;}public String getCategory(){return category;}public String getDescription(){return description;}public int getTotalCopies(){return totalCopies;}public int getAvailableCopies(){return availableCopies;}public int getReadingMinutes(){return readingMinutes;}public int getLearningValue(){return learningValue;}
 public void update(String title,String author,String isbn,String category,String description,int totalCopies,int readingMinutes,int learningValue){if(title==null||title.isBlank()||totalCopies<0||readingMinutes<0)throw new IllegalArgumentException("Invalid book details");int borrowed=this.totalCopies-this.availableCopies;if(totalCopies<borrowed)throw new IllegalArgumentException("Total copies below borrowed copies");this.title=title;this.author=n(author);this.isbn=n(isbn);this.category=n(category);this.description=n(description);this.totalCopies=totalCopies;this.availableCopies=totalCopies-borrowed;this.readingMinutes=readingMinutes;this.learningValue=learningValue;}
 public void borrow(){if(availableCopies==0)throw new IllegalStateException("No available copies");availableCopies--;}public void giveBack(){if(availableCopies>=totalCopies)throw new IllegalStateException("All copies available");availableCopies++;}
 private static String enc(String s){return s.replace("\\","\\\\").replace(",","\\c").replace("\n","\\n");}private static String dec(String s){return s.replace("\\n","\n").replace("\\c",",").replace("\\\\","\\");}
 public String toCsv(){return String.join(",",enc(id),enc(title),enc(author),enc(isbn),enc(category),enc(description),""+totalCopies,""+availableCopies,""+readingMinutes,""+learningValue);}
 public static Book fromCsv(String line){String[] p=line.split("(?<!\\\\),",-1);if(p.length!=10)throw new IllegalArgumentException("Malformed book row");return new Book(dec(p[0]),dec(p[1]),dec(p[2]),dec(p[3]),dec(p[4]),dec(p[5]),Integer.parseInt(p[6]),Integer.parseInt(p[7]),Integer.parseInt(p[8]),Integer.parseInt(p[9]));}
 @Override public String toString(){return String.format("%-5s %-28s %-20s %-14s %-14s %3d/%-3d",id,title.length()>28?title.substring(0,27)+"…":title,author.length()>20?author.substring(0,19)+"…":author,isbn,category,availableCopies,totalCopies);}
}